/// <summary>
/// Finds a record in the outbound message table
/// </summary>
/// <param name = "_recId">The record Id.</param>
/// <param name = "_forUpdate">Should the record be selected for update?</param>
/// <returns>The record found</returns>
public static OMGOutboundMessageTable findRecId(RecId    _recId, 
                                                boolean  _forUpdate = false)
{
    OMGOutboundMessageTable outboundMsgTable;
    ;

    outboundMsgTable.selectForUpdate(_forUpdate);

    if (_recId)
    {
        select firstonly outboundMsgTable
            where outboundMsgTable.RecId == _recId;
    }

    return outboundMsgTable;
}

/// <summary>
/// Finds a record in the outbound message table
/// </summary>
/// <param name = "_messageGUID">The message GUID</param>
/// <param name = "_forUpdate">Should the record be selected for update?</param>
/// <returns>A record</returns>
public static OMGOutboundMessageTable find(OMGMessageGUID   _messageGUID,
                                           boolean          _forUpdate = false)
{
    OMGOutboundMessageTable outboundMsgTable;
    ;

    outboundMsgTable.selectForUpdate(_forUpdate);

    if (_messageGUID)
    {
        select firstonly outboundMsgTable
            where outboundMsgTable.MessageGUID == _messageGUID;
    }

    return outboundMsgTable;
}

/// <summary>
/// Logs a processing error
/// </summary>
/// <param name = "_outboundMessageTableRecId">The RecId of the record in question</param>
/// <param name = "_errorLog">The error string</param>
public static void logError(RecId                   _outboundMessageTableRecId,
                            OMGTransactionErrorLog  _errorLog)
{
    OMGOutboundMessageTable  oMGOutboundMessageTable;
    ;

    ttsbegin;

    oMGOutboundMessageTable = OMGOutboundMessageTable::findRecId(_outboundMessageTableRecId, true);

    if (oMGOutboundMessageTable)
    {
        oMGOutboundMessageTable.MessageErrorLog  = _errorLog;
        oMGOutboundMessageTable.MessageStatus    = OMGProcessingStatus::Error;
        oMGOutboundMessageTable.update();
    }

    ttscommit;
}

/// <summary>
/// Checks if the message status changes from error to ready. If so, the errorLog field is cleared
/// </summary>
public void update()
{
    OMGOutboundMessageTable     outboundMessageTable_Orig = this.orig();
    ;

    if (outboundMessageTable_Orig.MessageStatus == OMGProcessingStatus::Error   &&
        this.MessageStatus                      == OMGProcessingStatus::Ready)
    {
        this.MessageErrorLog = '';
    }

    super();
}

/// <summary>
/// Creates an outbound message
/// </summary>
/// <param name = "_messageName">The name of the message</param>
/// <param name = "_messageTypeId">The message type</param>
/// <param name = "_message">The message content</param>
/// <param name = "_base64Encoded">Is the content base64 encoded</param>
/// <param name = "_company">The company the message should be processed in</param>
/// <param name = "_messageGuid">The message GUIS</param>
/// <param name = "_sourceDateTime">The source date/time</param>
/// <returns>The created record</returns>    
public static OMGOutboundMessageTable createOutboundMessage(OMGMessageName      _messageName,
                                                            OMGMessageTypeId    _messageTypeId,
                                                            OMGMessage          _message,
                                                            NoYesId             _base64Encoded  = NoYes::No,
                                                            DataAreaId          _company        = curExt(),
                                                            OMGMessageGUID      _messageGuid    = newGuid(),
                                                            OMGSourceDateTime   _sourceDateTime = DateTimeUtil::getSystemDateTime())
{
    OMGOutboundMessageTable     outboundMessageTable;
    ;

    outboundMessageTable.clear();
    outboundMessageTable.initValue();
    outboundMessageTable.MessageStatus  = OMGProcessingStatus::Ready;
    outboundMessageTable.MessageName    = _messageName;        
    outboundMessageTable.MessageTypeId  = _messageTypeId;
    outboundMessageTable.Message        = _message;
    outboundMessageTable.Base64Encoded  = _base64Encoded;
    outboundMessageTable.SourceCompany  = _company;
    outboundMessageTable.MessageGUID    = _messageGUID;        
    outboundMessageTable.SourceDateTime = _sourceDateTime;
    outboundMessageTable.insert();

    return outboundMessageTable;
}

/// <summary>
/// Formats a filename
/// </summary>
/// <param name = "_outboundMessageTable">The outbound message</param>    
/// <param name = "_dataContract">The data contract</param>
/// <returns>The filename</returns>
public static Filename generateFilename(OMGOutboundMessageTable         _outboundMessageTable,                                       
                                        OMGOutboundDataContract_Azure   _dataContract)
{
    Filename            filename;
    FilenameType        filenameType;
    OMGFilenamePattern  fileNamePattern = _dataContract.parmFilenamePattern();
    ;

    /*
    %1 = MessageGUID
    %2 = MessageTypeId
    %3 = MessageName
    %4 = SourceCompany
    %5 = SourceDateTime
    %6 = ExecutionDateTime (timenow of export)
    %7 = TargetDirectory        
    */

    filename = strFmt(fileNamePattern, _outboundMessageTable.MessageGUID, 
                                       _outboundMessageTable.MessageTypeId, 
                                       _outboundMessageTable.MessageName,
                                       _outboundMessageTable.SourceCompany,
                                       _outboundMessageTable.SourceDateTime,
                                       DateTimeUtil::getSystemDateTime(),
                                       _outboundMessageTable.TargetDirectory);

    // Removing illegal characters
    filename = strRem(filename, '\\');
    filename = strRem(filename, '/');
    filename = strRem(filename, ':');
    filename = strRem(filename, '*');
    filename = strRem(filename, '?');
    filename = strRem(filename, '"');
    filename = strRem(filename, '<');
    filename = strRem(filename, '>');
    filename = strRem(filename, '|');

    filenameType = _outboundMessageTable.FilenameType ? _outboundMessageTable.FilenameType : _dataContract.parmFileType();

    // Making sure that the filenameType starts with a '.' ex .xml
    if (!strScan(filenameType, '.', 1, 1))
    {
        filenameType = '.' + filenameType;
    }

    return filename + filenameType;
}

/// <summary>
/// Updates the status on a outbound message
/// </summary>
/// <param name = "_ourboundMessageRecId">The RecId of the message in question</param>
/// <param name = "_messageTypeTable">The message type</param>
/// <param name = "_processingStatus">The new status</param>
public static void updateStatus(RecId               _ourboundMessageRecId,
                                OMGMessageTypeTable _messageTypeTable,    
                                OMGProcessingStatus _processingStatus)
{
    OMGOutboundMessageTable     outboundMessageTable;
    ;

    ttsbegin;

    outboundMessageTable = OMGOutboundMessageTable::findRecId(_ourboundMessageRecId, true);

    if (outboundMessageTable)
    {
        if (_processingStatus == OMGProcessingStatus::Processed && _messageTypeTable.RequestRetentionPeriod == 0)
        {
            outboundMessageTable.delete();
        }
        else
        {
            outboundMessageTable.MessageStatus = _processingStatus;
            outboundMessageTable.update();
        }
    }

    ttscommit;
}
